CREATE VIEW dbo.IV_Q$AFERICAO_VENDA_MQ_IM ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , Q001_ZERO, Q001_UM, Q001_DOIS, Q001_TRES, Q001_QUATRO, Q001_CINCO, Q001_SEIS, Q001_SETE, Q001_OITO, Q001_NOVE, Q001_DEZ, Q002_INSATISFEITO, Q002_INDIFERENTE, Q002_SATISFEITO, Q003_INSATISFEITO, Q003_INDIFERENTE, Q003_SATISFEITO, Q004_INSATISFEITO, Q004_INDIFERENTE, Q004_SATISFEITO, RECOM_COLORADO_JD_VE, Q006_INSATISFEITO, Q006_INDIFERENTE, Q006_SATISFEITO, Q007_ESTRUTURA, Q007_AREA_VENDAS, Q007_AREA_PECAS, Q007_AREA_SERVICO, Q007_ORGANIZACAO, Q007_ESPACO_FISICO, PESQUISA_MQ_IMP)     AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.Q001_ZERO, TABF.Q001_UM, TABF.Q001_DOIS, TABF.Q001_TRES, TABF.Q001_QUATRO, TABF.Q001_CINCO, TABF.Q001_SEIS, TABF.Q001_SETE, TABF.Q001_OITO, TABF.Q001_NOVE, TABF.Q001_DEZ, TABF.Q002_INSATISFEITO, TABF.Q002_INDIFERENTE, TABF.Q002_SATISFEITO, TABF.Q003_INSATISFEITO, TABF.Q003_INDIFERENTE, TABF.Q003_SATISFEITO, TABF.Q004_INSATISFEITO, TABF.Q004_INDIFERENTE, TABF.Q004_SATISFEITO, TABF.RECOM_COLORADO_JD_VE, TABF.Q006_INSATISFEITO, TABF.Q006_INDIFERENTE, TABF.Q006_SATISFEITO, TABF.Q007_ESTRUTURA, TABF.Q007_AREA_VENDAS, TABF.Q007_AREA_PECAS, TABF.Q007_AREA_SERVICO, TABF.Q007_ORGANIZACAO, TABF.Q007_ESPACO_FISICO, TABF.PESQUISA_MQ_IMP    FROM IV_Q_AFERICAO_VENDA_MQ_IM TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA 